import './styles.css';
import { useState, useEffect, useCallback, useRef } from 'react';

const GRID_SIZE = 5;
const GOAL_POS = { x: 4, y: 4 };
const START_POS = { x: 0, y: 0 };

type Action = 'up' | 'down' | 'left' | 'right';
const ACTIONS: Action[] = ['up', 'down', 'left', 'right'];

interface QTable {
  [key: string]: { [action in Action]: number };
}

function getStateKey(x: number, y: number): string {
  return `${x},${y}`;
}

function initQTable(): QTable {
  const q: QTable = {};
  for (let x = 0; x < GRID_SIZE; x++) {
    for (let y = 0; y < GRID_SIZE; y++) {
      q[getStateKey(x, y)] = { up: 0, down: 0, left: 0, right: 0 };
    }
  }
  return q;
}

function getNextPos(x: number, y: number, action: Action): { x: number; y: number } {
  switch (action) {
    case 'up': return { x, y: Math.max(0, y - 1) };
    case 'down': return { x, y: Math.min(GRID_SIZE - 1, y + 1) };
    case 'left': return { x: Math.max(0, x - 1), y };
    case 'right': return { x: Math.min(GRID_SIZE - 1, x + 1), y };
  }
}

function chooseAction(q: QTable, x: number, y: number, epsilon: number): Action {
  // Epsilon-greedy: sometimes explore randomly
  if (Math.random() < epsilon) {
    return ACTIONS[Math.floor(Math.random() * ACTIONS.length)];
  }

  // Otherwise pick best action
  const state = getStateKey(x, y);
  const qValues = q[state];
  let bestAction = ACTIONS[0];
  let bestValue = qValues[bestAction];

  ACTIONS.forEach(action => {
    if (qValues[action] > bestValue) {
      bestValue = qValues[action];
      bestAction = action;
    }
  });

  return bestAction;
}

function GridCell({ 
  x, 
  y, 
  isRobot, 
  isGoal, 
  qValues,
  showLearning 
}: { 
  x: number; 
  y: number; 
  isRobot: boolean; 
  isGoal: boolean;
  qValues?: { [action in Action]: number };
  showLearning: boolean;
}) {
  const maxQ = qValues ? Math.max(...Object.values(qValues)) : 0;
  const minQ = qValues ? Math.min(...Object.values(qValues)) : 0;
  const range = maxQ - minQ || 1;

  // Color based on max Q value (how good this state is)
  const intensity = qValues && showLearning ? Math.min(1, maxQ / 10) : 0;
  const bgColor = showLearning && !isGoal 
    ? `rgba(34, 197, 94, ${intensity * 0.5})` 
    : undefined;

  return (
    <div 
      className={`grid-cell ${isGoal ? 'goal' : ''} ${isRobot ? 'robot' : ''}`}
      style={{ backgroundColor: bgColor }}
    >
      {isGoal && !isRobot && <span className="cell-content">🎯</span>}
      {isRobot && <span className="cell-content robot-emoji">🤖</span>}

      {showLearning && qValues && !isGoal && (
        <div className="q-arrows">
          <div className="q-arrow up" style={{ opacity: 0.3 + (qValues.up - minQ) / range * 0.7 }}>↑</div>
          <div className="q-arrow down" style={{ opacity: 0.3 + (qValues.down - minQ) / range * 0.7 }}>↓</div>
          <div className="q-arrow left" style={{ opacity: 0.3 + (qValues.left - minQ) / range * 0.7 }}>←</div>
          <div className="q-arrow right" style={{ opacity: 0.3 + (qValues.right - minQ) / range * 0.7 }}>→</div>
        </div>
      )}
    </div>
  );
}

function StatsPanel({ 
  episode, 
  steps, 
  totalReward, 
  successRate,
  recentRewards 
}: { 
  episode: number; 
  steps: number; 
  totalReward: number;
  successRate: number;
  recentRewards: number[];
}) {
  return (
    <div className="stats-panel">
      <h3>Training Stats</h3>
      <div className="stats-grid">
        <div className="stat">
          <span className="stat-value">{episode}</span>
          <span className="stat-label">Episodes</span>
        </div>
        <div className="stat">
          <span className="stat-value">{steps}</span>
          <span className="stat-label">Current Steps</span>
        </div>
        <div className="stat">
          <span className="stat-value">{totalReward.toFixed(1)}</span>
          <span className="stat-label">Episode Reward</span>
        </div>
        <div className="stat">
          <span className="stat-value">{(successRate * 100).toFixed(0)}%</span>
          <span className="stat-label">Success Rate</span>
        </div>
      </div>

      <div className="reward-history">
        <span className="history-label">Recent episode rewards:</span>
        <div className="history-bars">
          {recentRewards.slice(-10).map((r, i) => (
            <div 
              key={i} 
              className={`history-bar ${r > 0 ? 'positive' : 'negative'}`}
              style={{ height: `${Math.min(100, Math.abs(r) * 5)}%` }}
              title={`Episode ${episode - recentRewards.length + i + 1}: ${r.toFixed(1)}`}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [qTable, setQTable] = useState<QTable>(initQTable);
  const [robotPos, setRobotPos] = useState(START_POS);
  const [isTraining, setIsTraining] = useState(false);
  const [episode, setEpisode] = useState(0);
  const [steps, setSteps] = useState(0);
  const [totalReward, setTotalReward] = useState(0);
  const [showLearning, setShowLearning] = useState(true);
  const [speed, setSpeed] = useState(200);
  const [recentRewards, setRecentRewards] = useState<number[]>([]);
  const [successes, setSuccesses] = useState(0);

  const trainingRef = useRef(false);
  const qTableRef = useRef(qTable);

  useEffect(() => {
    qTableRef.current = qTable;
  }, [qTable]);

  const learningRate = 0.1;
  const discountFactor = 0.95;
  const epsilon = Math.max(0.1, 0.5 - episode * 0.01); // Decay exploration

  const runStep = useCallback(() => {
    if (!trainingRef.current) return;

    setRobotPos(currentPos => {
      const action = chooseAction(qTableRef.current, currentPos.x, currentPos.y, epsilon);
      const nextPos = getNextPos(currentPos.x, currentPos.y, action);

      // Calculate reward
      let reward = -0.1; // Small penalty for each step
      const reachedGoal = nextPos.x === GOAL_POS.x && nextPos.y === GOAL_POS.y;

      if (reachedGoal) {
        reward = 10; // Big reward for goal
      } else if (nextPos.x === currentPos.x && nextPos.y === currentPos.y) {
        reward = -0.5; // Penalty for hitting wall
      }

      // Q-learning update
      const currentState = getStateKey(currentPos.x, currentPos.y);
      const nextState = getStateKey(nextPos.x, nextPos.y);
      const nextQValues = qTableRef.current[nextState];
      const maxNextQ = Math.max(...Object.values(nextQValues));

      const oldQ = qTableRef.current[currentState][action];
      const newQ = oldQ + learningRate * (reward + discountFactor * maxNextQ - oldQ);

      setQTable(prev => ({
        ...prev,
        [currentState]: {
          ...prev[currentState],
          [action]: newQ
        }
      }));

      setSteps(s => s + 1);
      setTotalReward(r => r + reward);

      // Check if episode is done
      if (reachedGoal || steps > 50) {
        // Episode finished
        setEpisode(e => e + 1);
        setRecentRewards(prev => [...prev.slice(-19), totalReward + reward]);
        if (reachedGoal) {
          setSuccesses(s => s + 1);
        }
        setSteps(0);
        setTotalReward(0);
        return START_POS;
      }

      return nextPos;
    });
  }, [epsilon, steps, totalReward]);

  useEffect(() => {
    if (!isTraining) return;

    trainingRef.current = true;
    const interval = setInterval(runStep, speed);

    return () => {
      trainingRef.current = false;
      clearInterval(interval);
    };
  }, [isTraining, runStep, speed]);

  const handleReset = () => {
    setIsTraining(false);
    setQTable(initQTable());
    setRobotPos(START_POS);
    setEpisode(0);
    setSteps(0);
    setTotalReward(0);
    setRecentRewards([]);
    setSuccesses(0);
  };

  const successRate = episode > 0 ? successes / episode : 0;

  return (
    <div className="app">
      <div className="header">
        <h1>Robot Trainer</h1>
        <p className="subtitle">
          Watch reinforcement learning in action! The robot learns to reach the goal through trial and error.
        </p>
      </div>

      <div className="main-content">
        <div className="game-panel">
          <div className="grid">
            {Array.from({ length: GRID_SIZE }).map((_, y) => (
              <div key={y} className="grid-row">
                {Array.from({ length: GRID_SIZE }).map((_, x) => (
                  <GridCell
                    key={x}
                    x={x}
                    y={y}
                    isRobot={robotPos.x === x && robotPos.y === y}
                    isGoal={GOAL_POS.x === x && GOAL_POS.y === y}
                    qValues={qTable[getStateKey(x, y)]}
                    showLearning={showLearning}
                  />
                ))}
              </div>
            ))}
          </div>

          <div className="controls">
            <button 
              className={`train-btn ${isTraining ? 'stop' : 'start'}`}
              onClick={() => setIsTraining(!isTraining)}
            >
              {isTraining ? 'Pause Training' : 'Start Training'}
            </button>
            <button className="reset-btn" onClick={handleReset}>
              Reset
            </button>
          </div>

          <div className="settings">
            <div className="setting">
              <label>Speed: {speed}ms</label>
              <input
                type="range"
                min="50"
                max="500"
                value={speed}
                onChange={(e) => setSpeed(parseInt(e.target.value))}
              />
            </div>
            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={showLearning}
                onChange={(e) => setShowLearning(e.target.checked)}
              />
              Show what robot learned
            </label>
          </div>
        </div>

        <div className="info-panel">
          <StatsPanel
            episode={episode}
            steps={steps}
            totalReward={totalReward}
            successRate={successRate}
            recentRewards={recentRewards}
          />

          <div className="legend">
            <h3>How It Works</h3>
            <div className="legend-item">
              <span className="legend-icon">🤖</span>
              <span>Robot (learning agent)</span>
            </div>
            <div className="legend-item">
              <span className="legend-icon">🎯</span>
              <span>Goal (+10 reward)</span>
            </div>
            <div className="legend-item">
              <span className="legend-icon">📉</span>
              <span>Each step: -0.1 (encourages efficiency)</span>
            </div>
            <div className="legend-item">
              <span className="legend-icon">🧱</span>
              <span>Hit wall: -0.5 (discourages bad moves)</span>
            </div>
          </div>

          {showLearning && (
            <div className="learning-legend">
              <h4>Reading the Grid</h4>
              <p>Arrows show which direction the robot thinks is best from each cell. Brighter = more confident.</p>
              <p>Green cells = high value states (close to goal)</p>
            </div>
          )}
        </div>
      </div>

      <div className="insight-box">
        <h3>What's Happening?</h3>
        <p>
          This is <strong>reinforcement learning</strong>! The robot starts knowing nothing.
          Each time it moves, it gets feedback: +10 for reaching the goal, -0.1 for each step (to encourage efficiency),
          and -0.5 for hitting walls.
        </p>
        <p>
          <strong>The learning process:</strong> The robot remembers which actions worked well from each position.
          Over time, it builds a mental map of "from here, going right is good" — this is called a Q-table.
        </p>
        <p>
          <strong>Exploration vs Exploitation:</strong> Early on, the robot tries random moves (exploration).
          As it learns, it increasingly uses what it knows (exploitation). Watch the success rate climb!
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #7c3aed 0%, #6366f1 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

.app {
  max-width: 900px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 1rem;
}

.main-content {
  display: grid;
  grid-template-columns: auto 280px;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

@media (max-width: 700px) {
  .main-content {
    grid-template-columns: 1fr;
  }
}

.game-panel {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.grid {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 1rem;
}

.grid-row {
  display: flex;
  gap: 4px;
}

.grid-cell {
  width: 60px;
  height: 60px;
  background: #f3f4f6;
  border: 2px solid #e5e7eb;
  border-radius: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  transition: all 0.2s;
}

.grid-cell.goal {
  background: #fef3c7;
  border-color: #f59e0b;
}

.grid-cell.robot {
  background: #dbeafe;
  border-color: #3b82f6;
}

.cell-content {
  font-size: 1.75rem;
}

.robot-emoji {
  animation: bounce 0.5s ease infinite;
}

@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}

.q-arrows {
  position: absolute;
  inset: 2px;
  display: grid;
  grid-template-areas:
    ". up ."
    "left . right"
    ". down .";
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: 1fr 1fr 1fr;
  font-size: 0.7rem;
  color: #6366f1;
  pointer-events: none;
}

.q-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
}

.q-arrow.up { grid-area: up; }
.q-arrow.down { grid-area: down; }
.q-arrow.left { grid-area: left; }
.q-arrow.right { grid-area: right; }

.controls {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.train-btn {
  flex: 1;
  padding: 0.75rem;
  border: none;
  border-radius: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.train-btn.start {
  background: linear-gradient(135deg, #22c55e, #16a34a);
  color: white;
}

.train-btn.start:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(34, 197, 94, 0.4);
}

.train-btn.stop {
  background: linear-gradient(135deg, #ef4444, #dc2626);
  color: white;
}

.reset-btn {
  padding: 0.75rem 1.5rem;
  background: #f3f4f6;
  color: #374151;
  border: none;
  border-radius: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.reset-btn:hover {
  background: #e5e7eb;
}

.settings {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.setting label {
  display: block;
  font-size: 0.85rem;
  color: #374151;
  margin-bottom: 0.25rem;
}

.setting input[type="range"] {
  width: 100%;
  height: 6px;
  background: #e5e7eb;
  border-radius: 3px;
  outline: none;
  -webkit-appearance: none;
}

.setting input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 16px;
  height: 16px;
  background: #6366f1;
  border-radius: 50%;
  cursor: pointer;
}

.checkbox-label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
  color: #374151;
  cursor: pointer;
}

/* Info Panel */
.info-panel {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.stats-panel {
  background: white;
  border-radius: 1rem;
  padding: 1rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.stats-panel h3 {
  font-size: 0.9rem;
  color: #374151;
  margin-bottom: 0.75rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.stat {
  background: #f9fafb;
  padding: 0.5rem;
  border-radius: 0.5rem;
  text-align: center;
}

.stat-value {
  display: block;
  font-size: 1.25rem;
  font-weight: 700;
  color: #6366f1;
}

.stat-label {
  font-size: 0.65rem;
  color: #6b7280;
  text-transform: uppercase;
}

.reward-history {
  background: #f9fafb;
  padding: 0.5rem;
  border-radius: 0.5rem;
}

.history-label {
  font-size: 0.7rem;
  color: #6b7280;
  display: block;
  margin-bottom: 0.25rem;
}

.history-bars {
  display: flex;
  gap: 2px;
  height: 30px;
  align-items: flex-end;
}

.history-bar {
  flex: 1;
  min-width: 8px;
  border-radius: 2px 2px 0 0;
  transition: height 0.2s;
}

.history-bar.positive {
  background: #22c55e;
}

.history-bar.negative {
  background: #ef4444;
}

.legend {
  background: white;
  border-radius: 1rem;
  padding: 1rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.legend h3 {
  font-size: 0.9rem;
  color: #374151;
  margin-bottom: 0.5rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8rem;
  color: #4b5563;
  margin-bottom: 0.25rem;
}

.legend-icon {
  width: 24px;
  text-align: center;
}

.learning-legend {
  background: #eef2ff;
  border-radius: 0.5rem;
  padding: 0.75rem;
}

.learning-legend h4 {
  font-size: 0.8rem;
  color: #4338ca;
  margin-bottom: 0.25rem;
}

.learning-legend p {
  font-size: 0.75rem;
  color: #6366f1;
  line-height: 1.4;
  margin-bottom: 0.25rem;
}

.learning-legend p:last-child {
  margin-bottom: 0;
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.5rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.75rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}
